CREATE COLUMN TABLE "TEST_AP"."OPMX" ("AbsEntry" INTEGER CS_INT NOT NULL , "Total" DECIMAL(21,6) CS_FIXED, "Currency" NVARCHAR(3), "Rate" DECIMAL(21,6) CS_FIXED, "Uid" NVARCHAR(100) NOT NULL , "RFC" NVARCHAR(20), "CreateDate" LONGDATE CS_LONGDATE, "FileDate" LONGDATE CS_LONGDATE, "FileName" NVARCHAR(254), "JVBatchNum" INTEGER CS_INT, "JVTransId" INTEGER CS_INT, "JETransId" INTEGER CS_INT, "Type" NVARCHAR(1) DEFAULT 'P', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OPMX_UID" ON "TEST_AP"."OPMX" ( "Uid" ASC )